CREATE TABLE tt_late_fee_policies(id TEXT PRIMARY KEY,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),charge_id TEXT NOT NULL REFERENCES tt_charges(id),version INTEGER NOT NULL,terms TEXT NOT NULL,reference TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(charge_id,version));
CREATE TABLE tt_late_fees(id TEXT PRIMARY KEY,source_charge_id TEXT NOT NULL UNIQUE REFERENCES tt_charges(id),fee_charge_id TEXT NOT NULL UNIQUE REFERENCES tt_charges(id),policy_id TEXT NOT NULL REFERENCES tt_late_fee_policies(id),snapshot TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE tt_late_fee_runs(id TEXT PRIMARY KEY,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),on_day TEXT NOT NULL,snapshot TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE tt_late_fee_waivers(id TEXT PRIMARY KEY REFERENCES tt_adjustments(id),fee_id TEXT NOT NULL REFERENCES tt_late_fees(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),reason TEXT NOT NULL,on_day TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
